    public event Action OnDied;
    public event Action<float> OnDamaged;

    /// <summary>
    /// 鐢?EnemyCore 鍦ㄨ缃?MaxHealth 鍚庤皟鐢ㄣ€?
    /// 纭繚 _health 浠庢渶缁?MaxHealth 鍒濆鍖栵紝閬垮厤鏁版嵁婧愪笉涓€鑷淬€?
    /// </summary>
    public void Initialize()
    {
