        _health = MaxHealth;
        _initialized = true;
    }

    private void Awake()
    {
        // 涓嶅啀鑷姩鍒濆鍖栵紝鐢辫皟鐢ㄦ柟锛圗nemyCore锛夋帶鍒跺垵濮嬪寲鏃舵満
